    def test_edited_pinned_briefing_is_refused(self):
        repo = self.repo
        repo.install_pre_commit()
        repo.terms()
        repo.stage(guard.SETTINGS, '{"public_repo": true}')
        scanner = repo.root / 'script/public_hygiene.py'
        source = scanner.read_text()
        originals = {}
        for name, pin in guard.PUBLIC_BRIEFING_SHA256.items():
            # Synthetic public briefings keep this fixture independent of the
            # one-time cutover tooling, which is absent after the split.
            content = f'# {name}\nFollow the project conventions.\n'
            originals[name] = content
            repo.stage(name, content)
            self.assertEqual(source.count(pin), 1)
            source = source.replace(pin, hashlib.sha256(content.encode()).hexdigest())
        repo.stage('script/public_hygiene.py', source)
        repo.commit()

        for name, original in originals.items():
            with self.subTest(briefing=name):
                before = repo.git('rev-parse', 'HEAD').stdout
                edited = original + 'Record useful project learnings.\n'
                repo.stage(name, edited)
                refused = repo.git('commit', '-m', 'note: edit briefing', check=False)
                self.assertNotEqual(refused.returncode, 0, 'edited pinned briefing accepted')
                self.assertIn(f'{name}:1: briefing-pin'.encode(), refused.stdout + refused.stderr)
                self.assertEqual(repo.git('rev-parse', 'HEAD').stdout, before)
                self.assertEqual(repo.git('show', ':' + name).stdout, edited.encode())

                old_pin = hashlib.sha256(original.encode()).hexdigest()
                new_pin = hashlib.sha256(edited.encode()).hexdigest()
                source = scanner.read_text()
                self.assertEqual(source.count(old_pin), 1)
                repo.stage('script/public_hygiene.py', source.replace(old_pin, new_pin))
                accepted = repo.git('commit', '-m', 'note: update briefing and pin', check=False)
                self.assertEqual(accepted.returncode, 0, accepted.stdout + accepted.stderr)
                self.assertEqual(repo.git('show', 'HEAD:' + name).stdout, edited.encode())

    def test_pre_push_refuses_each_hookless_operation(self):
        for operation in ('am', 'cherry-pick', 'revert', 'rebase'):
            for kind, name, payload in (('private-file', RECORD, 'ordinary private record'),
                                         ('decision-cite', 'note.txt', DEC),
                                         ('home-path', 'note.txt', HOME_HIT)):
                with self.subTest(operation=operation, kind=kind):
                    repo = Repository()
                    self.addCleanup(repo.close)
                    repo.install_pre_commit()
                    for hook in ('commit-msg', 'pre-push'):
                        repo.stage('script/hooks/' + hook, (HERE / 'hooks' / hook).read_bytes())
                        (repo.root / 'script/hooks' / hook).chmod(0o755)
                        repo.git('add', '--', 'script/hooks/' + hook)
                    repo.stage('.gitignore', 'private' + '/\n')
                    repo.terms()
                    repo.terms()
                    repo.stage(guard.SETTINGS, '{"public_repo": true}')
                    repo.git('branch', '-M', 'master')
                    base = repo.commit()
                    with tempfile.TemporaryDirectory(prefix='hygiene-remote-') as remote:
                        repo.git('clone', '--bare', '--', str(repo.root), remote)
                        repo.git('remote', 'add', 'origin', remote)
                        repo.stage(name, payload)
                        leaking = repo.commit()
                        patch_bytes = repo.git('format-patch', '-1', '--stdout', leaking).stdout
                        repo.git('checkout', '-B', 'topic', base)
                        if operation == 'am':
                            repo.git('am', data=patch_bytes)
                        elif operation == 'cherry-pick':
                            repo.git('cherry-pick', leaking)
                        elif operation == 'revert':
                            repo.git('checkout', '-B', 'topic', leaking)
                            repo.git('rm', '--', name)
                            removal = repo.commit()
                            repo.git('revert', '--no-edit', removal)
                        else:
                            repo.stage('upstream.txt', 'new base')
                            upstream = repo.commit()
                            repo.git('checkout', '-B', 'topic', leaking)
                            repo.git('rebase', '--onto', upstream, base)
                        tip = repo.git('rev-parse', 'HEAD').stdout.decode().strip()
                        self.assertEqual(repo.git('show', tip + ':' + name).stdout, payload.encode())
                        # The pushed ref need not be the checked-out branch.
                        repo.git('checkout', '--detach', base)
                        ref = 'refs/tags/proof' if operation == 'revert' else 'refs/heads/topic'
                        result = repo.git('push', 'origin', tip + ':' + ref, check=False)
                        self.assertNotEqual(result.returncode, 0, 'hookless leak was pushed')
                        self.assertIn(kind.encode(), result.stderr)
                        self.assertEqual(repo.git('ls-remote', 'origin', ref).stdout, b'')

    def test_pre_push_clean_refs_deletion_and_reinstall(self):
        repo = self.repo
        repo.install_pre_commit()
        for name in ('install-hooks.sh', 'hooks/commit-msg', 'hooks/pre-push'):
            repo.stage('script/' + name, (HERE / name).read_bytes())
            (repo.root / 'script' / name).chmod(0o755)
            repo.git('add', '--', 'script/' + name)
        repo.stage('.gitignore', 'private' + '/\n')
        repo.terms()
        repo.terms()
        repo.stage(guard.SETTINGS, '{"public_repo": true}')
        repo.git('branch', '-M', 'master')
        repo.commit()
        hook = (repo.root / 'script/hooks/pre-push').read_bytes()
        for _ in range(2):
            installed = subprocess.run(['bash', 'script/install-hooks.sh'], cwd=repo.root,
                                       env=repo.env, capture_output=True)
            self.assertEqual(installed.returncode, 0, installed.stderr)
            self.assertEqual((repo.root / 'script/hooks/pre-push').read_bytes(), hook)
        with tempfile.TemporaryDirectory(prefix='hygiene-remote-') as remote:
            repo.git('clone', '--bare', '--', str(repo.root), remote)
            repo.git('remote', 'add', 'origin', remote)
            repo.stage('clean.txt', 'ordinary content')
            repo.commit()
            for ref in ('refs/heads/topic', 'refs/tags/clean', 'refs/notes/proof'):
                result = repo.git('push', 'origin', 'HEAD:' + ref, check=False)
                self.assertEqual(result.returncode, 0, result.stderr)
                result = repo.git('push', 'origin', ':' + ref, check=False)
                self.assertNotEqual(result.returncode, 0, result.stderr)
                self.assertIn(b'non-fast-forward', result.stderr)

    def test_deletions_keep_kit_gates_in_both_layouts(self):
        for public in (False, True):
            repo = Repository()
            self.addCleanup(repo.close)
            repo.stage(guard.SETTINGS, json.dumps({'public_repo': public}))
            tip = repo.commit()
            for ref, allowed, diagnostic in (('master', False, 'RATCHET_ALLOW_PUSH'),
                                              ('master', True, 'non-fast-forward'),
                                              ('topic', False, 'non-fast-forward')):
                with self.subTest(public=public, ref=ref, allowed=allowed):
                    env = dict(repo.env, RATCHET_DEFAULT_BRANCH='master')
                    env.pop('RATCHET_ALLOW_PUSH', None)
                    if allowed:
                        env['RATCHET_ALLOW_PUSH'] = '1'
                    result = subprocess.run(['bash', HERE / 'hooks/pre-push', 'origin', 'unused'],
                                            cwd=repo.root, env=env, capture_output=True,
                                            input=f'(delete) {"0" * 40} refs/heads/{ref} {tip}\n'.encode())
                    self.assertEqual(result.returncode, 1, result.stderr)
                    self.assertIn(diagnostic.encode(), result.stderr)
                    self.assertNotIn(b'public hygiene', result.stderr)

    def test_binary_decode_falls_back_without_losing_raw_findings(self):
        # Font-like NUL distribution formerly selected UTF-16 and raised on a
        # surrogate. PNG, executable and arbitrary binary bytes stay raw too.
        cases = [b'\0\1\0\0' + b'A\0' * 40 + b'\0\xd8',
                 b'\x89PNG\r\n\x1a\n' + bytes(range(256)),
                 b'\xcf\xfa\xed\xfe' + bytes(range(256)),
                 b'\xff\xfeA\0\0\xd8', b'\xff\xfe\0\0A\0\0',
                 bytes(range(256)) * 32]
        for index, data in enumerate(cases):
            with self.subTest(index=index):
                try:
                    decoded = guard.text_bytes(data)
                except guard.ReadError as error:
                    self.fail(str(error))
                self.assertEqual(decoded, data)
                self.repo.stage('binary.data', data + b'\n' + DEC.encode())
                result = self.repo.run()
                self.assertEqual(result.returncode, 1, result.stderr)
                self.assertIn(b'decision-cite', result.stderr)

    def test_unicode_controls_in_encoded_text_are_scanned(self):
        encodings = [('utf-16-le', b'\xff\xfe'), ('utf-16-be', b'\xfe\xff'),
                     ('utf-16-le', b''), ('utf-16-be', b''),
                     ('utf-32-le', b'\xff\xfe\0\0'), ('utf-32-be', b'\0\0\xfe\xff')]
        cases = {}
        for encoding, bom in encodings:
            for char in ('\u00a0', '\u200d', '\u200b', '\u2028', '\ufeff', '\ue000', '\f'):
                for cite, rule in (('DEC' + '-91', 'decision-cite'),
                                   ('docs/' + 'LOG.md', 'private-path-cite')):
                    name = f'text-{len(cases)}.strings'
                    data = bom + ('ordinary ' + char + cite + char + ' text\n').encode(encoding)
                    cases[name] = rule
                    self.repo.stage(name, data)
        expected = [(name, 1, rule) for name, rule in cases.items()]
        self.assert_scan(expected)
        self.assert_scan(expected, '--tree')
        base = self.repo.git('rev-parse', 'HEAD').stdout.decode().strip()
        tip = self.repo.commit()
        result = self.repo.run('--range', base + '..' + tip)
        self.assertEqual(result.returncode, 1, result.stderr)
        for name, number, rule in expected:
            self.assertIn(f'{name}:{number}: {rule}:'.encode(), result.stderr)

        for value in range(32):
            data = b'\xff\xfe' + ('ordinary ' + chr(value) + ' text').encode('utf-16-le')
            with self.subTest(control=value):
                expected = data[2:].decode('utf-16-le').encode() if value in (9, 10, 12, 13) else data
                self.assertEqual(guard.text_bytes(data), expected)

