    def test_public_destination_uses_repository_path_on_any_host(self):
        tip = self.repo.git('rev-parse', 'HEAD').stdout.decode().strip()
        for host in ('github.com-jared', 'mirror.example'):
            for suffix in ('', '.git'):
                for url in (f'git@{host}:jaredatch/pensieve{suffix}',
                            f'ssh://git@{host}/jaredatch/pensieve{suffix}',
                            f'https://{host}/jaredatch/pensieve{suffix}'):
                    with self.subTest(url=url):
                        result = self.repo.run('--pre-push', url, '0' * 40, tip, 'refs/heads/topic')
                        self.assertEqual(result.returncode, 1, result.stderr)
                        self.assertIn(b'public-guard-ancestry', result.stderr)
            for name in ('pensieve-app', 'pensieve-private', 'pensieve-other'):
                url = f'git@{host}:jaredatch/{name}.git'
                result = self.repo.run('--pre-push', url, '0' * 40, tip, 'refs/heads/topic')
                self.assertEqual(result.returncode, 0, result.stderr)
        self.repo.git('config', 'url.git@github.com-jared:.insteadOf', 'fixture:')
        self.repo.git('remote', 'add', 'rewritten', 'fixture:jaredatch/pensieve.git')
        url = self.repo.git('remote', 'get-url', '--push', 'rewritten').stdout.decode().strip()
        self.assertEqual(url, 'git@github.com-jared:jaredatch/pensieve.git')
        result = self.repo.run('--pre-push', url, '0' * 40, tip, 'refs/heads/topic')
        self.assertEqual(result.returncode, 1, result.stderr)
        self.assertIn(b'public-guard-ancestry', result.stderr)

