    def test_pre_push_batches_refs_and_default_lookup(self):
        repo = self.repo
        repo.install_pre_commit()
        repo.stage('script/hooks/pre-push', (HERE / 'hooks/pre-push').read_bytes())
        repo.terms()
        repo.stage(guard.SETTINGS, '{"public_repo": true}')
        repo.git('branch', '-M', 'master')
        repo.commit()
        with tempfile.TemporaryDirectory(prefix='hygiene-batch-') as temp:
            remote = Path(temp) / 'remote'
            repo.git('clone', '--bare', '--', str(repo.root), str(remote))
            tip = repo.git('rev-parse', 'HEAD').stdout.decode().strip()
            bins = Path(temp) / 'bin'
            bins.mkdir()
            log = Path(temp) / 'calls'
            for name in ('git', 'python3'):
                real = shutil.which(name)
                wrapper = bins / name
                wrapper.write_text('#!/bin/sh\nprintf "%s\\n" "' + name + ' $*" >> "$CALL_LOG"\nexec "' + real + '" "$@"\n')
                wrapper.chmod(0o755)
            env = dict(repo.env, PATH=str(bins) + os.pathsep + os.environ['PATH'], CALL_LOG=str(log))
            lines = ''.join(f'HEAD {tip} {ref} {"0" * 40}\n' for ref in
                            ('refs/heads/topic', 'refs/tags/clean', 'refs/notes/proof'))
            result = subprocess.run(['bash', HERE / 'hooks/pre-push', 'origin', str(remote)],
                                    cwd=repo.root, env=env, input=lines.encode(), capture_output=True)
            self.assertEqual(result.returncode, 0, result.stderr)
            calls = log.read_text().splitlines()
            self.assertEqual(sum(line.startswith('python3 ') for line in calls), 1, calls)
            self.assertEqual(sum(line.startswith('git ls-remote ') for line in calls), 1, calls)

    def assert_scan(self, expected, *args):
        result = self.repo.run(*args)
        output = result.stderr.decode('utf-8', 'replace')
        self.assertEqual(result.returncode, 1 if expected else 0, output)
        actual = set()
        for line in output.splitlines():
            path, number, rule, _ = line.split(':', 3)
            actual.add((path, int(number), rule.strip()))
        self.assertEqual(actual, set(expected), output)

    def test_generated_rule_shape_transfer_sweep(self):
        self.repo.terms()
        expected = set()
        transfers = []
        # Every text rule crosses byte shape, filename, pass/fail, and transfer.
        for rule, hit in HITS.items():
            for shape, make in SHAPES.items():
                for filename in ('plain', 'with spaces', 'a"quote\'s', 'café-雪'):
                    for transfer in ('add', 'rename', 'copy'):
                        for positive in (False, True):
                            name = f'{rule}/{shape}/{filename}-{transfer}-{positive}.txt'
                            data, line = make(hit if positive else SAFE[rule])
                            if transfer == 'add':
                                transfers.append((None, name, data, transfer))
                            else:
                                source = '/'.join(('docs', 'plans', name))
                                self.repo.write(source, data)
                                transfers.append((source, name, data, transfer))
                            if positive and line:
                                expected.add((name, line, rule))
        self.repo.git('add', '--', *[source for source, _, _, _ in transfers if source])
        self.repo.commit()
        for source, name, data, transfer in transfers:
            self.repo.write(name, data)
            if transfer == 'rename':
                (self.repo.root / source).unlink()
        changed = [name for _, name, _, _ in transfers]
        changed += [source for source, _, _, kind in transfers if kind == 'rename']
        self.repo.git('add', '--', *changed)
        home_variants = ['~' + 'someone/data', HOME_HIT.replace('/', r'\/'),
                          '~/.claude/projects/' + '-Users' + '-someone-Projects-app/']
        home_variants += ['~' + user + '/data' for user in ('Alice', '_service', 'a.b-c_9')]
        home_variants += ['/'.join(('', 'Users', user, 'x')) for user in ('Élodie', '1password', 'jane.doe')]
        project_home = '-Users' + '-name'
        home_variants += ['~/.claude/projects/' + project_home + '/abc.jsonl',
                          project_home + '-Projects-app/', project_home]
        home_variants += [prefix + project_home + suffix
                          for prefix, suffix in ((' ', ' '), ('"', '"'), ("'", "'"), ('`', '`'))]
        home_variants += ['[s](~/.claude/projects/' + project_home + ')',
                          '<~/.claude/projects/' + project_home + '>',
                          'cwd=' + project_home + '-Projects', 'a:' + project_home + '-x',
                          '(' + project_home + '-Projects-x)']
        home_variants += [prefix + '~' + 'name/x' + suffix
                          for prefix, suffix in ((' ', ''), ('"', '"'), ("'", "'"), ('`', '`'),
                                                 ('(', ')'), ('[', ']'), ('<', '>'))]
        for index, hit in enumerate(home_variants):
            path = f'home-variant-{index}.txt'
            self.repo.stage(path, 'first\n' + hit + '\n')
            expected.add((path, 2, 'home-path'))
        self.repo.stage('named-home.md', 'first\n ~' + 'name/x\n')
        expected.add(('named-home.md', 2, 'home-path'))
        for index, (name, domain) in enumerate((('someone', 'pensieve.ai'), ('bob', 'company.mov'))):
            path = f'email-suffix-{index}.txt'
            self.repo.stage(path, 'first\n' + name + '@' + domain + '\n')
            expected.add((path, 2, 'email'))
        self.assert_scan(expected)
        self.assert_scan(expected, '--tree')
        print(f'generated sweep: {len(transfers)} files, {len(expected)} exact file/line/rule hits per mode')

    def test_image_sweep(self):
        expected, transfers = set(), []
        for shape, make in SHAPES.items():
            for name in ('plain', 'with spaces', 'a"quote\'s', 'café-雪'):
                for transfer in ('add', 'rename', 'copy'):
                    data, _ = make('image payload')
                    for allowed in (False, True):
                        prefix = ASSETS if allowed else 'images/'
                        path = f'{prefix}{shape}/{name}-{transfer}.png'
                        source = '/'.join(('docs', 'plans', path)) if transfer != 'add' else None
                        if source:
                            self.repo.write(source, data)
                        transfers.append((source, path, data, transfer))
                        if not allowed:
                            expected.add((path, 1, 'image-location'))
        self.repo.git('add', '--', *[source for source, _, _, _ in transfers if source])
        self.repo.commit()
        for source, path, data, transfer in transfers:
            self.repo.write(path, data)
            if transfer == 'rename':
                (self.repo.root / source).unlink()
        changed = [path for _, path, _, _ in transfers]
        changed += [source for source, _, _, kind in transfers if kind == 'rename']
        self.repo.git('add', '--', *changed)
        self.assert_scan(expected)
        self.assert_scan(expected, '--tree')
        self.repo.commit()
        self.repo.stage('clean.txt', b'clean\n')
        self.assert_scan([])
        for index, data in enumerate((b'\x89PNG\r\n\x1a\n', b'\xff\xd8\xff',
                                     b'<svg xmlns="x"></svg>', b'RIFF1234WEBP')):
            self.repo.stage(f'disguised-{index}.bin', data)
        disguised = [(f'disguised-{i}.bin', 1, 'image-location') for i in range(4)]
        self.assert_scan(disguised)
        self.repo.commit()
        committed = list(expected) + disguised
        expected = []
        for extension in ('sketch', 'fig', 'psd', 'ai', 'svgz', 'jxl', 'heic', 'mov', 'mp4', 'webm'):
            path = f'images/media.{extension}'
            self.repo.stage(path, b'opaque media payload')
            self.repo.stage(ASSETS + f'media.{extension}', b'opaque media payload')
            expected.append((path, 1, 'image-location'))
        for extension in ('md', 'markdown', 'html', 'htm'):
            path = f'embedded.{extension}'
            self.repo.stage(path, 'first\n<img src="data:image/png;base64,AAAA">\n')
            expected.append((path, 2, 'image-location'))
        self.assert_scan(expected)
        self.assert_scan(committed + expected, '--tree')

