    def test_staged_public_merge_requires_adoption_for_every_parent(self):
        for position in ('merge-head', 'later-merge-head', 'head', 'valid'):
            with self.subTest(position=position):
                repo = Repository()
                self.addCleanup(repo.close)
                repo.install_pre_commit()
                repo.terms()
                repo.stage(guard.SETTINGS, '{"public_repo": true}')
                base = repo.commit()
                repo.stage('side.txt', 'safe side')
                side = repo.commit()
                repo.git('read-tree', '--empty')
                repo.stage('docs/' 'plans/PLAN-99.md', DEC)
                foreign = repo.commit(parents=[])
                head = foreign if position == 'head' else base
                repo.git('update-ref', 'HEAD', head)
                repo.git('read-tree', '--reset', '-u', head)
                targets = [side, foreign] if position == 'later-merge-head' else [
                    base if position == 'head' else side if position == 'valid' else foreign]
                repo.git('merge', '--no-ff', '--no-commit', '-s', 'ours', '--allow-unrelated-histories', *targets)
                if position == 'head':
                    # Restore the public index so the refusal must name HEAD's
                    # ancestry, not merely missing policy or a leaking tree.
                    repo.git('read-tree', '--reset', '-u', base)
                pending = repo.git('rev-parse', '--git-path', 'MERGE_HEAD').stdout.strip().decode()
                pending = repo.root / pending
                self.assertEqual(pending.read_text().splitlines(), targets)
                env = dict(repo.env, GIT_INDEX_FILE=str(repo.root / '.git/index'))
                results = [('staged', repo.run()), ('project-check', repo.run('--project-check', env=env)),
                           ('hook', repo.git('commit', '-m', 'note: fixture merge', check=False))]
                for mode, result in results:
                    with self.subTest(mode=mode):
                        if position == 'valid':
                            self.assertEqual(result.returncode, 0, result.stderr)
                        else:
                            self.assertEqual(result.returncode, 1, result.stderr)
                            self.assertIn(b'public-guard-ancestry', result.stderr)
                            self.assertIn(foreign.encode(), result.stderr)

