        changed = [name for _, name, _, _ in transfers]
        changed += [source for source, _, _, kind in transfers if kind == 'rename']
        self.repo.git('add', '--', *changed)
        self.assert_scan([])
        self.assert_scan([], '--tree')
        self.repo.terms()
        self.repo.stage(guard.SETTINGS, '{"public_repo": true}')
        expected = [(name, 1, 'private-file') for _, name, _, _ in transfers]
