    def prepare_project_replay(self):
        self.repo.install_pre_commit()
        for name in ('ci-replay.sh', 'tmp-tidy.sh'):
            target = self.repo.root / 'script' / name
            shutil.copy2(HERE / name, target)
            self.repo.git('add', '--', 'script/' + name)
        conf = (self.repo.root / 'script/ratchet.conf').read_text()
        # Observe the real caller's environment without setting the signal.
        conf += ('\nRATCHET_PROJECT_CHECK=\'printf "CALLER_INDEX=%s\\n" '
                 '"${GIT_INDEX_FILE+present}"; \'"$RATCHET_PROJECT_CHECK"\n')
        self.repo.stage('script/ratchet.conf', conf)
        return self.repo.commit()

    def replay_project(self, revisions):
        return subprocess.run(['bash', 'script/ci-replay.sh', revisions], cwd=self.repo.root,
                              env=self.repo.env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

