    def test_project_diff_generated_text_and_filename_sweep(self):
        self.repo.terms()
        names = ('plain.txt', 'space name.txt', 'quote".txt', 'back\\slash.txt',
                 'tab\tname.txt', 'line\nname.txt', 'café-雪.txt')
        expected = set()
        for rule, hit in HITS.items():
            for shape in ('lf', 'crlf', 'no-final-newline', 'first', 'last'):
                data, number = SHAPES[shape](hit)
                for index, name in enumerate(names):
                    path = f'added/{rule}-{shape}-{index}/{name}'
                    self.repo.stage(path, data)
                    expected.add((path, number, rule))
        # Header-shaped content must stay content, including multiple hunks.
        self.repo.stage('headers.txt', 'old\nkeep\nold\n')
        self.repo.stage('removed.txt', DEC + '\n')
        # Commit only these two baselines, keeping the generated files staged.
        before = self.repo.git('rev-parse', 'HEAD').stdout.strip().decode()
        tree = self.repo.git('write-tree').stdout.strip().decode()
        # A separate baseline repo isn't needed: remove the generated paths only
        # from a temporary index when constructing the parent commit.
        with tempfile.TemporaryDirectory() as directory:
            env = dict(self.repo.env, GIT_INDEX_FILE=str(Path(directory) / 'index'))
            def temporary_git(*args):
                return subprocess.run(['git', *args], cwd=self.repo.root, env=env,
                                      check=True, stdout=subprocess.PIPE).stdout
            temporary_git('read-tree', tree)
            temporary_git('rm', '-qr', '--cached', '--', 'added')
            parent_tree = temporary_git('write-tree').strip().decode()
        parent = self.repo.git('commit-tree', parent_tree, '-p', before,
                               data=b'fixture baseline\n').stdout.strip().decode()
        self.repo.git('update-ref', 'HEAD', parent)
        self.repo.stage('headers.txt', '+++ ' + DEC + '\nkeep\n@@ ' + DEC + '\n')
        expected.update({('headers.txt', 1, 'decision-cite'), ('headers.txt', 3, 'decision-cite')})
        self.repo.git('rm', '-q', '--', 'removed.txt')
        private = '/'.join(('docs', 'research', 'fixture.txt'))
        self.repo.stage(private, DEC + '\n')
        for quote_paths in ('true', 'false'):
            for context in ('-U0', '-U3'):
                with self.subTest(quote_paths=quote_paths, context=context):
                    diff = self.repo.git('-c', 'core.quotePath=' + quote_paths, 'diff',
                                         '--cached', '--no-prefix', '--no-renames', context).stdout
                    with in_directory(self.repo.root):
                        self.assertEqual(set(guard.scan_project_diff(diff, None)), expected)
        self.assertEqual(len(expected), 212)

