    def test_full_range_covers_content_missing_from_project_diff(self):
        self.prepare_project_replay()
        private = '/'.join(('docs', 'research', 'fixture.txt'))
        self.repo.stage(private, DEC + '\n')
        base = self.repo.commit()
        self.repo.git('mv', '--', private, 'renamed.txt')
        renamed = self.repo.commit()
        self.repo.stage('binary.dat', b'\0' + DEC.encode() + b'\n')
        head = self.repo.commit()
        # A rename-aware diff has no text for either change. The callback cannot
        # invent those bytes, while the authoritative range scan reads blobs.
        diff = self.repo.git('diff', '--no-prefix', '-U0', '-M', base, head).stdout
        self.assertIn(b'similarity index 100%', diff)
        self.assertIn(b'Binary files', diff)
        self.assertNotIn(('+' + DEC).encode(), diff)
        with in_directory(self.repo.root):
            self.assertEqual(guard.scan_project_diff(diff, None), [])
        # The kit's diff-tree expands the rename, so its actual replay catches it.
        replay = self.replay_project(base + '..' + renamed)
        self.assertEqual(replay.returncode, 1, replay.stdout + replay.stderr)
        self.assertIn(b'renamed.txt:1: decision-cite', replay.stderr)
        binary_only = self.replay_project(renamed + '..' + head)
        self.assertEqual(binary_only.returncode, 0, binary_only.stdout + binary_only.stderr)
        full = self.repo.run('--range', base + '..' + head)
        self.assertEqual(full.returncode, 1, full.stdout + full.stderr)
        for path in ('renamed.txt', 'binary.dat'):
            self.assertIn(f'{path}:1: decision-cite'.encode(), full.stderr)

