    def test_unreadable_index_blob_worktree_and_policy(self):
        index = self.repo.root / '.git/index'
        content = index.read_bytes()
        index.write_bytes(b'broken index')
        for args in ((), ('--tree',)):
            result = self.repo.run(*args)
            self.assertEqual(result.returncode, 2)
            self.assertIn(b'index', result.stderr)
        index.write_bytes(content)
        self.repo.stage('unreadable.txt', 'unique staged content')
        (self.repo.root / 'unreadable.txt').chmod(0)
        result = self.repo.run('--tree')
        self.assertEqual(result.returncode, 2)
        self.assertIn(b'unreadable.txt', result.stderr)
        (self.repo.root / 'unreadable.txt').chmod(0o600)
        oid = self.repo.git('rev-parse', ':unreadable.txt').stdout.strip().decode()
        (self.repo.root / '.git/objects' / oid[:2] / oid[2:]).unlink()
        result = self.repo.run()
        self.assertEqual(result.returncode, 2)
        self.assertIn(b'blob unreadable.txt', result.stderr)
        self.repo.git('rm', '-q', '-f', '--', 'unreadable.txt')
        manifest = (self.repo.root / guard.PATHS).read_bytes()
        self.repo.git('rm', '-q', '--', guard.PATHS)
        result = self.repo.run('--tree')
        self.assertNotEqual(result.returncode, 0, result.stderr)
        self.assertIn(guard.PATHS.encode(), result.stderr)
        self.assertIn(b'restore', result.stderr)
        self.repo.stage(guard.PATHS, manifest)
        # A tracked but unreadable list remains an input error, not a deletion.
        (self.repo.root / guard.PATHS).unlink()
        result = self.repo.run('--tree')
        self.assertEqual(result.returncode, 2, result.stderr)
        self.assertIn(guard.PATHS.encode(), result.stderr)
        oid = self.repo.git('rev-parse', ':' + guard.PATHS).stdout.strip().decode()
        (self.repo.root / '.git/objects' / oid[:2] / oid[2:]).unlink()
        result = self.repo.run()
        self.assertEqual(result.returncode, 2, result.stderr)
        self.assertIn(guard.PATHS.encode(), result.stderr)

    def test_producer_failure_never_reports_partial_success(self):
        original = guard.git
        with in_directory(self.repo.root), patch.dict(os.environ, self.repo.env, clear=True):
            for mode in ([], ['--tree']):
                for command in ('ls-files', 'cat-file'):
                    def fail(*args):
                        if args[0] == command:
                            raise guard.ReadError('cannot read ' + command + ' injected failure')
                        return original(*args)
                    with patch.object(guard, 'git', fail), contextlib.redirect_stderr(io.StringIO()) as out:
                        # Tree reads working bytes; inject that producer instead.
                        if mode and command == 'cat-file':
                            with patch.object(guard, 'disk_bytes', side_effect=guard.ReadError('cannot read tracked file')):
                                code = guard.main(mode)
                        else:
                            code = guard.main(mode)
                    self.assertEqual(code, 2, out.getvalue())
                    self.assertIn('cannot read', out.getvalue())


    def test_range_skips_commits_that_predate_the_guard(self):
        guarded_base = self.repo.git('rev-parse', 'HEAD').stdout.strip().decode()
        self.repo.git('rm', '-q', '--', guard.PATHS, guard.SETTINGS)
        # A separate root models a repository's history before adoption.
        old_root = self.repo.commit(parents=[])
        self.repo.stage('legacy.txt', DEC)
        old_tip = self.repo.commit()
        self.repo.stage(guard.PATHS, (HERE / 'private-paths.txt').read_bytes())
        self.repo.stage(guard.SETTINGS, b'{"public_repo": false}')
        adoption = self.repo.commit()
        result = self.repo.run('--range', guarded_base + '..' + adoption)
        self.assertEqual(result.returncode, 0, result.stderr)
        for commit in (old_root, old_tip):
            lines = [line for line in result.stdout.decode().splitlines() if commit in line]
            self.assertEqual(len(lines), 1, result.stdout)
            self.assertIn('skipped', lines[0])
        self.assertNotIn(adoption.encode(), result.stdout)
        self.repo.stage('new.txt', DEC)
        merge = self.repo.commit(parents=[adoption, old_tip])
        result = self.repo.run('--range', adoption + '..' + merge)
        self.assertEqual(result.returncode, 1, result.stderr)
        self.assertIn(f'commit {merge}: new.txt:1: decision-cite'.encode(), result.stderr)
        self.repo.git('rm', '-q', '--', guard.PATHS)
        for parents in ([merge], [old_tip, merge]):
            dropped = self.repo.commit(parents=parents)
            result = self.repo.run('--range', merge + '..' + dropped)
            self.assertEqual(result.returncode, 1, result.stderr)
            self.assertIn(b'restore', result.stderr)
            self.assertIn(dropped.encode(), result.stderr)
            self.assertIn(guard.PATHS.encode(), result.stderr)
            self.assertNotIn(f'commit {dropped}: skipped'.encode(), result.stdout)

