    def test_personal_terms_fall_back_to_main_worktree(self):
        self.repo.stage('term.txt', TERM)
        self.repo.commit()
        child = self.repo.root / 'linked checkout'
        self.repo.git('worktree', 'add', '--detach', str(child), 'HEAD')
        relative = '/'.join(('private', 'hygiene-personal-terms'))
        self.repo.terms()
        def run(*args):
            return subprocess.run([str(HERE / 'public-hygiene.sh'), *args], cwd=child,
                                  env=self.repo.env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        # Make the same line a staged addition in the linked worktree.
        (child / 'new.txt').write_text(TERM)
        self.repo.git('-C', str(child), 'add', '--', 'new.txt')
        for mode in ((), ('--tree',)):
            result = run(*mode)
            self.assertEqual(result.returncode, 1, result.stderr)
            self.assertIn(b'new.txt:1: personal-term', result.stderr)
        local = child / relative
        local.parent.mkdir()
        local.write_text('local-only-term')
        self.assertEqual(run().returncode, 0)
        # Explicit overrides never fall back, including an absent override.
        self.assertEqual(run('--personal-terms', relative + '-missing').returncode, 0)
        main = self.repo.root / relative
        for file in (main, local):
            file.chmod(0)
            try:
                for mode in ((), ('--tree',)):
                    result = run(*mode)
                    self.assertEqual(result.returncode, 2, result.stderr)
                    self.assertIn(os.fsencode(file), result.stderr)
            finally:
                file.chmod(0o600)
        local.unlink()
        local.symlink_to('missing')
        self.assertEqual(run().returncode, 2)
        local.unlink()
        main.unlink()
        self.assertEqual(run().returncode, 0)

    def test_image_headers_distinguish_documents_from_text(self):
        import struct
        # A 1x1 24-bit BMP, and icon containers with one payload.
        bitmap = (b'BM' + struct.pack('<IHHI', 58, 0, 0, 54) +
                  struct.pack('<IiiHHIIiiII', 40, 1, 1, 1, 24, 0, 4, 0, 0, 0, 0) + b'\0' * 4)
        png = b'\x89PNG\r\n\x1a\n'
        icon = b'\0\0\x01\0\x01\0' + struct.pack('<BBBBHHII', 1, 1, 0, 0, 1, 32, len(png), 22) + png
        icns = b'icns' + struct.pack('>I', 16 + len(png)) + b'icp4' + struct.pack('>I', 8 + len(png)) + png
        images = [png, b'\xff\xd8\xff', b'GIF89a', b'RIFF1234WEBP', b'II*\0', b'MM\0*',
                  bitmap, icon, icns, b'\0\0\0\x18ftypheic\0\0\0\0mif1heic',
                  b'\0\0\0\x18ftypavif\0\0\0\0mif1avif',
                  b'<svg width="1"/>', b'<?xml version="1.0"?>\n<svg />']
        for number, data in enumerate(images):
            self.repo.stage(f'image-{number}.dat', data)
        text = [b'BMW notes', b'icns is an icon format', b'const x = "<svg width=1>"',
                b'<html><svg width="1"/></html>', b'\0\0\x01\0not an icon',
                b'icns\0\0\0\x01', b'BM\0\0\0\0notes']
        for number, data in enumerate(text):
            self.repo.stage(f'text-{number}.txt', data)
        expected = [(f'image-{n}.dat', 1, 'image-location') for n in range(len(images))]
        self.assert_scan(expected)
        self.assert_scan(expected, '--tree')

