    def test_svg_adversarial_prologs_are_bounded(self):
        comments = b'<!---->' * 600
        cases = [(b'<!DOCTYPE svg [' + comments, False),
                 (b'<!DOCTYPE svg [' + comments + b']><svg />', True),
                 (comments + b'<html><svg /></html>', False),
                 (b'<!DOCTYPE svg [<!ENTITY x "' + b'[' * 20000, False)]
        command = ('import sys, public_hygiene as guard; '
                   'sys.exit(0 if guard.image_file("vector.dat", sys.stdin.buffer.read()) '
                   '== bool(int(sys.argv[1])) else 1)')
        for data, expected in cases:
            with self.subTest(size=len(data), expected=expected):
                try:
                    result = subprocess.run([sys.executable, '-B', '-c', command, str(int(expected))],
                                            input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                            env=dict(self.repo.env, PYTHONPATH=str(HERE)), timeout=5)
                except subprocess.TimeoutExpired:
                    self.fail('SVG recognition exceeded five seconds for an adversarial prolog')
                self.assertEqual(result.returncode, 0, result.stderr)

