    def range_acceptance_fixture(self):
        base = self.repo.git('rev-parse', 'HEAD').stdout.strip().decode()
        self.repo.stage('leak.txt', MAIL)
        commit = self.repo.commit()
        entry = dict(commit=commit, path='leak.txt', line=1, rule='email',
                     reason='An earlier rule allowed this fixture.')
        return base + '..' + commit, entry

    def accepted_range(self, revisions, data, symlink=False):
        path = self.repo.root / ACCEPTANCES
        if path.is_symlink():
            path.unlink()
        if symlink:
            path.unlink(missing_ok=True)
            path.symlink_to('absent.json')
            self.repo.git('add', '--', ACCEPTANCES)
        else:
            self.repo.stage(ACCEPTANCES, data)
        base, tip = revisions.split('..')
        accepted_base = self.repo.commit(parents=[base])
        return accepted_base + '..' + tip

    def test_range_acceptance_requires_all_four_fields(self):
        revisions, entry = self.range_acceptance_fixture()
        for field, value in (('commit', '0' * 40), ('path', 'other.txt'), ('line', 2),
                             ('rule', 'decision-cite')):
            with self.subTest(field=field):
                accepted = self.accepted_range(revisions, json.dumps([dict(entry, **{field: value})]))
                result = self.repo.run('--range', accepted)
                self.assertEqual(result.returncode, 1, result.stderr)
                self.assertIn(b'leak.txt:1: email', result.stderr)
                self.assertNotIn(b'accepted', result.stdout)
        accepted = self.accepted_range(revisions, json.dumps([entry, dict(entry, line=99)]))
        result = self.repo.run('--range', accepted)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(len(result.stdout.splitlines()), 1)
        for value in ('accepted', entry['commit'], entry['path'], entry['rule'], entry['reason']):
            self.assertIn(value.encode(), result.stdout)
        (self.repo.root / ACCEPTANCES).unlink()
        self.assertEqual(self.repo.run('--range', revisions).returncode, 1)

    def test_range_acceptance_malformed_list_fails_closed(self):
        revisions, entry = self.range_acceptance_fixture()
        invalid = ['{', '{}', '[null]', json.dumps([dict(entry, line=True)]),
                   json.dumps([dict(entry, line=0)]), json.dumps([dict(entry, commit='abc')]),
                   json.dumps([dict(entry, path='../file')]), json.dumps([dict(entry, reason='')]),
                   json.dumps([dict(entry, rule=None)]), json.dumps([dict(entry, extra=1)]),
                   json.dumps([{key: value for key, value in entry.items() if key != 'reason'}]),
                   json.dumps([entry, entry])]
        for data in invalid:
            with self.subTest(data=data):
                accepted = self.accepted_range(revisions, data)
                result = self.repo.run('--range', accepted)
                self.assertEqual(result.returncode, 2, result.stderr)
                self.assertIn(ACCEPTANCES.encode(), result.stderr)

    def test_range_acceptance_unreadable_list_fails_closed(self):
        revisions, entry = self.range_acceptance_fixture()
        accepted = self.accepted_range(revisions, json.dumps([entry]))
        oid = self.repo.git('rev-parse', accepted.split('..')[0] + ':' + ACCEPTANCES).stdout.strip().decode()
        original = guard.git
        def unreadable(*args):
            if args == ('cat-file', 'blob', oid):
                raise guard.ReadError('cannot read fixture blob')
            return original(*args)
        with in_directory(self.repo.root), patch.object(guard, 'git', side_effect=unreadable), \
                contextlib.redirect_stderr(io.StringIO()) as output:
            self.assertEqual(guard.main(['--range', accepted]), 2)
            self.assertIn(ACCEPTANCES, output.getvalue())
        accepted = self.accepted_range(revisions, '', symlink=True)
        self.assertEqual(self.repo.run('--range', accepted).returncode, 2)

    def test_range_acceptance_cannot_waive_staged_tree_or_hook(self):
        revisions, entry = self.range_acceptance_fixture()
        accepted = self.accepted_range(revisions, json.dumps([entry]))
        self.assertEqual(self.repo.run('--range', accepted).returncode, 0)
        base = revisions.split('..')[0]
        self.repo.git('update-ref', 'HEAD', base)
        self.repo.git('rm', '--cached', '--', ACCEPTANCES)
        self.repo.install_pre_commit()
        for data in (json.dumps([entry]), '{'):
            self.repo.write(ACCEPTANCES, data)
            for args in ((), ('--tree',)):
                self.assert_scan([('leak.txt', 1, 'email')], *args)
            result = self.repo.git('commit', '-qm', 'fixture', check=False)
            self.assertNotEqual(result.returncode, 0)
            self.assertIn(b'leak.txt:1: email', result.stderr)
            self.assertNotIn(b'scan incomplete', result.stderr)
        (self.repo.root / ACCEPTANCES).chmod(0)
        for args in ((), ('--tree',)):
            self.assert_scan([('leak.txt', 1, 'email')], *args)
        (self.repo.root / ACCEPTANCES).chmod(0o600)

